// Implementation outline
function maxScorePartition(s, k) {
  const n = s.length;
  const dist = Array.from({length:n}, ()=>Array(n).fill(0));
  for (let l=0;l<n;l++) {
    const seen = new Set();
    for (let r=l;r<n;r++) { seen.add(s[r]); dist[l][r] = seen.size; }
  }
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const par = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for (let i=1;i<=n;i++) dp[i][1] = dist[0][i-1];
  for (let t=2;t<=k;t++){
    for (let i=t;i<=n;i++){
      for (let j=t-1;j<i;j++){
        const v = dp[j][t-1] + dist[j][i-1];
        if (v > dp[i][t]) { dp[i][t] = v; par[i][t] = j; }
      }
    }
  }
  // reconstruction omitted
  return {dp, par};
}
```

## Why This Is Asked

Tests the ability to model non-crossing, higher-arity structures with DP and reconstruct a solution.

## Key Concepts

- DP state dp[i][t] for i and t
- Non-crossing triple formation
- Reconstruction via backpointers
- Time/space trade-offs and optimization path

## Code Example

```javascript
function maxTriples(A, n, k) {
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-Infinity));
  const prv = Array.from({length: n+1}, () => Array(k+1).fill(null));
  dp[0][0] = 0;
  for (let i=1; i<=n; i++) {
    for (let t=0; t<=k; t++) {
      dp[i][t] = dp[i-1][t];
      if (t>0) {
        for (let i1=1; i1<i; i1++) {
          for (let j=i1+1; j<i; j++) {
            const prev = (i1>=2 ? dp[i1-1][t-1] : (t-1===0 ? 0 : -Infinity));
            const val = prev + A[i1-1]*A[j-1]*A[i-1];
            if (val > dp[i][t]) { dp[i][t] = val; prv[i][t] = {i1, j}; }
          }
        }
      }
    }
  }
  // reconstruction logic would backtrack using prv
  return {value: dp[n][k], triples: []};
}
```

## Why This Is Asked
Tests constrained path DP with an extra state (turns). Encourages explicit DP state design, directional transitions, and plan for path reconstruction.

## Key Concepts
- Grid DP with 4D state (i, j, t, dir)
- Transition logic depends on last direction
- Reconstruction via parent pointers
- Edge cases when k is large vs. maximum turns (n+m-2)

## Code Example
```javascript
function maxPathWithTurns(grid, k){
  const n = grid.length, m = grid[0].length;
  const NEG = -1e15;
  const dp = Array.from({length:n}, ()=>
    Array.from({length:m}, ()=>
      Array.from({length:k+1}, ()=> Array(2).fill(NEG))))
  dp[0][0][0][0] = grid[0][0];
  dp[0][0][0][1] = grid[0][0];
  for(let i=0;i<n;i++){
    for(let j=0;j<m;j++){
      for(let t=0;t<=k;t++){
        for(let dir=0;dir<2;dir++){
          const cur = dp[i][j][t][dir];
          if(cur===NEG) continue;
          // move right
          if(j+1<m){
            const nt = t + (dir===0?0:1);
            if(nt<=k) dp[i][j+1][nt][0] = Math.max(dp[i][j+1][nt][0], cur + grid[i][j+1]);
          }
          // move down
          if(i+1<n){
            const nt = t + (dir===1?0:1);
            if(nt<=k) dp[i+1][j][nt][1] = Math.max(dp[i+1][j][nt][1], cur + grid[i+1][j]);
          }
        }
      }
    }
  }
  let ans = NEG;
  for(let t=0;t<=k;t++){
    ans = Math.max(ans, dp[n-1][m-1][t][0], dp[n-1][m-1][t][1]);
  }
  return ans;
}
```

